import{t as e}from"./api-CliBdh_X.js";var t={getDashboard:async()=>(await e.get(`/students/parent-dashboard/`)).data,getFees:async()=>(await e.get(`/students/parent-fees/`)).data,getTransactions:async()=>(await e.get(`/students/parent-fees/`)).data,getAnalytics:async t=>(await e.get(`/students/parent-analytics/?student=${t}`)).data,getChildSummary:async t=>(await e.get(`/students/parent-child-summary/${t}/`)).data,getComparison:async()=>(await e.get(`/students/parent-comparison/`)).data,getAttendance:async t=>{let n=await e.get(`/attendance/records/?student=${t}`);return n.data.results||n.data},updateProfile:async t=>(await e.patch(`/auth/me/`,t)).data,initiatePayment:async t=>(await e.post(`/students/parent-payment/`,t)).data};export{t};